const rawData = items[0].json.data;

const result = rawData.map(d => {
  return {
    id: d.id,
    name: d.name,
    type: d.type,
    status: d.status?.name || null,
    parentId: d.parent?.feature?.id || d.parent?.component?.id || null,
    owner: d.owner?.email || null,
    description: d.description 
      ? d.description.replace(/<[^>]*>/g, '').trim() 
      : null,  // ✅ plain text only
    createdAt: d.createdAt ? new Date(d.createdAt).toISOString().split("T")[0] : null,
    updatedAt: d.updatedAt ? new Date(d.updatedAt).toISOString().split("T")[0] : null,
    link: d.links?.html || null,
  };
});

return result.map(r => ({ json: r }));
